/// The prefix hecto (`h`): 10^2.
pub const HECTO: Unit<{ SIUnit::prefix(Exact::int(100)) }> = Unit::ONE;
/// The prefix deca (`da`): 10^1.
pub const DECA: Unit<{ SIUnit::prefix(Exact::int(10)) }> = Unit::ONE;
/// The prefix deci (`d`): 10^-1.
pub const DECI: Unit<{ SIUnit::prefix(Exact::dec(1, -1)) }> = Unit::ONE;
/// The prefix centi (`c`): 10^-2.
pub const CENTI: Unit<{ SIUnit::prefix(Exact::dec(1, -2)) }> = Unit::ONE;
/// The prefix milli (`m`): 10^-3.
